import React, {Component} from 'react';
import {Dimensions, Image, ScrollView, Text, TouchableNativeFeedback, View} from 'react-native';
import {bindActionCreators} from 'redux';
import {connect} from 'react-redux';
import styles from './HomeStyles';
import NavigationBar from '../Basic/NavigationBar';
import {goTo} from "../../Redux/Navigation/NavigationActions";

const screen = Dimensions.get('window');

class CompletedCourse extends Component {
  showStars = () => {
    let stars = [];
    const goldenStar = <Image
      style={styles.ratingStars}
      source={{uri: 'data:image/png;base64,'}}
    />;
    const greyStar = <Image
      style={styles.ratingStars}
      source={{uri: 'data:image/png;base64,'}}
    />;
    for (let i = 0; i < 5; i++) {
      if (i < this.state.rateNow) {
        stars.push(goldenStar);
      }
      else {
        stars.push(greyStar);
      }
    }
    return stars.map((item, index) => (
      <TouchableNativeFeedback
        onPress={() => this.setState({rateNow: index + 1})}
      >
        {item}
      </TouchableNativeFeedback>
    ));
  }

  constructor() {
    super();
    this.state = {
      chapterData: [
        {
          title: 'Introduction to Matrices',
          content: [
            {
              type: 'video',
              name: 'Introduction to Matrices',
              completed: true,
              info: '5 Minutes'
            },
            {
              type: 'assignment',
              name: 'Assignment 1',
              completed: true,
              info: '16 Questions'
            }
          ]
        },
        {
          title: 'Types of Matrices',
          content: [
            {
              type: 'video',
              name: 'Types of Matrices',
              completed: true,
              info: '10 Minutes',
            },
            {
              type: 'assignment',
              name: 'Assignment 1',
              completed: false,
              info: '20 Questions',
            },
            {
              type: 'assignment',
              name: 'Assignment 2',
              completed: false,
              info: '20 Questions',
            }
          ]
        },
      ],
      rateNow: 0,
    };
  }

  render() {
    const {chapterData, rateNow} = this.state;
    return (
      <View
        style={[styles.container, {paddingTop: 0, elevation: 100, height: screen.height, backgroundColor: 'white'}]}>
        <Image
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            height: '17.5%',
            width: '100%',
          }}
          source={{uri: 'data:image/png;base64,'}}
        />
        <NavigationBar noDashboard={true} leftButtonStyle={'BACK_WHITE'} leftButtonAction={this.props.history.goBack}/>
        <Text style={styles.sectionTitleCompleted}>Matrices</Text>
        <View style={styles.completedTopHeader}>
          <View style={styles.teacherProfileImageContainer}>
            <Image
              style={styles.teacherProfileImage}
              source={{uri: 'http://unsplash.it/502'}}
            />
          </View>
          <View style={styles.assignmentImageContainer}>
            <Image
              style={styles.teacherProfileImage}
              source={{uri: 'data:image/png;base64,'}}
            />
            <Text style={styles.assignmentNumberText}>43</Text>
          </View>
          <View style={styles.videosImageContainer}>
            <Image
              style={styles.teacherProfileImage}
              source={{uri: 'data:image/png;base64,'}}
            />
            <Text style={styles.assignmentNumberText}>37</Text>
          </View>
          <View style={styles.teacherInfoBox}>
            <Text style={styles.teacherInfoName}>Ashutosh Ag</Text>
            <Text style={styles.teacherInfoInstitute}>Impulse Coaching</Text>
          </View>
        </View>
        <View style={styles.ratingContainer}>
          <View style={styles.horizontalLine}/>
          {
            rateNow
              ? <View style={styles.ratingStarsContainer}>
                {
                  this.showStars()
                }
              </View>
              : <TouchableNativeFeedback
                onPress={() => this.setState({rateNow: 1})}
              >
                <View style={styles.rateNowButton}>
                  <Image
                    style={styles.overlayBg}
                    resizeMode={'contain'}
                    source={
                      {uri: 'data:image/png;base64,'}
                    }
                  />
                  <Text style={styles.rateNowText}>Rate Now</Text>
                </View>
              </TouchableNativeFeedback>
          }
        </View>
        <ScrollView style={{width: '100%'}} contentContainerStyle={{backgroundColor: '#fff'}}>
          {
            chapterData.map((chapter, index) => (
              <View
                style={styles.chapterCard}
                key={'chapterCards' + index}>
                <View style={styles.chapterSectionTitleSection}>
                  <Image
                    style={styles.chapterSectionTitleIcon}
                    source={{uri: 'data:image/png;base64,'}}
                  />
                  <Text style={styles.chapterSectionTitleText}>{chapter.title}</Text>
                </View>
                <View style={styles.chapterCardContent}>
                  {
                    chapter.content.map((content, index) => {
                      let lineStyle = {};
                      if (index === 0) {
                        lineStyle = {
                          top: '50%',
                          height: '50%',
                        }
                      }
                      else if (index === chapter.content.length - 1) {
                        lineStyle = {
                          top: 0,
                          height: '50%',
                        }
                      }
                      return (
                        <View
                          key={'chapterContentItems' + index}
                          style={styles.content}>
                          <View style={[
                            styles.progressLineIndicator,
                            {
                              backgroundColor: content.completed ? '#56b64a' : '#a4a4a4'
                            }
                          ]}/>
                          <View style={[styles.contentLine, lineStyle]}/>
                          <View style={styles.contentIconContainer}>
                            <Image
                              style={styles.contentIcon}
                              source={{uri: 'http://unsplash.it/65'}}
                            />
                          </View>
                          <Text style={styles.contentName}>{content.name}</Text>
                          <View style={styles.contentDescriptionContainer}>
                            <Text style={styles.contentDescription}>{content.info}</Text>
                            <Image
                              style={styles.sectionCompleteDescriptionTickIcon}
                              resizeMode={'contain'}
                              source={{uri: 'data:image/png;base64,'}}
                            />
                          </View>
                        </View>
                      )
                    })
                  }
                </View>
              </View>
            ))
          }
        </ScrollView>
      </View>
    )
  }
}

const mapStateToProps = state => ({
  section: state.navigation.currentSection
});
const mapDispatchToProps = dispatch => bindActionCreators({
  goTo: goTo,
}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(CompletedCourse);